const s = $('Find settings').first().json;
const products = (($input.first().json.data || {}).products || { nodes: [] }).nodes;
const domainsFor = vendor => {
  const k = Object.keys(s.manufacturer_domains).find(v => v.toLowerCase() === String(vendor || '').toLowerCase());
  return k ? s.manufacturer_domains[k].map(d => d.toLowerCase().replace(/^www\./, '')) : [];
};
const cached = $('Read cached searches').all().map(i => i.json).filter(r => r.query);
return products.map(p => {
  const sku = ((p.variants.nodes[0] || {}).sku || '').trim();
  const model = ((p.mpn || {}).value || (s.use_sku_if_no_mpn ? sku : '')).trim();
  const domains = domainsFor(p.vendor);
  // One plain search per product. The manufacturer's domains are kept in code, not with site:,
  // because DataForSEO charges about five times as much for a site: search.
  const query = p.vendor + ' ' + model + ' ' + s.search_words;
  const hit = cached.find(r => r.query === query);
  return { json: {
    product_id: p.id.split('/').pop(), title: p.title, vendor: p.vendor, model, domains,
    manufacturer_url: (p.page || {}).value || '', query,
    cached_results: hit ? JSON.parse(hit.results || '[]') : null,
    skip: !model ? 'no model number' : !domains.length ? 'no manufacturer domains listed for ' + p.vendor : ''
  } };
});

// Why Code: one product needs one to three page fetches, and which pages to follow depends on the first page's links.
const s = $('Find settings').first().json;
const p = $input.item.json;
if (!p.manufacturer_url) return { json: { ...p, page_links: [], pages_read: [] } };
const origin = u => (/^https?:\/\/[^\/?#]+/i.exec(u) || [''])[0];
const abs = (href, base) => {
  href = href.replace(/&amp;/g, '&').trim();
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith('//')) return 'https:' + href;
  if (href.startsWith('/')) return origin(base) + href;
  return base.replace(/[^\/]*([?#].*)?$/, '') + href;
};
const host = u => ((/^https?:\/\/([^\/:?#]+)/i.exec(u) || [])[1] || '').toLowerCase().replace(/^www\./, '');
const official = u => { const h = host(u); return !!h && p.domains.some(d => h === d || h.endsWith('.' + d)); };
const linksOf = (html, base) => [...html.matchAll(/<a\b[^>]*?href=["']([^"'#][^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi)].map(m => ({
  url: abs(m[1], base),
  title: (((/aria-label=["']([^"']+)/i.exec(m[0]) || [])[1]) || m[2].replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim().slice(0, 200)
}));
const get = async url => {
  try { return String(await this.helpers.httpRequest({ url, headers: { 'User-Agent': s.user_agent }, timeout: 20000, json: false })); }
  catch (e) { return ''; }
};
// Pages for this model only: the slug ("tapo-c211") in the path, and the same locale as the manufacturer page.
const slug = p.model.toLowerCase().replace(/\([^)]*\)/g, '').trim().replace(/[\s_]+/g, '-');
const locale = (/^https?:\/\/[^\/]+\/([a-z]{2}(?:-[a-z]{2})?)\//i.exec(p.manufacturer_url) || [])[1] || '';
const pages = [p.manufacturer_url], read = [], found = [];
while (pages.length && read.length < s.max_pages) {
  const url = pages.shift();
  const html = await get(url);
  read.push(url + (html ? '' : ' (no reply)'));
  for (const l of linksOf(html, url)) {
    if (!official(l.url)) continue;
    found.push({ ...l, source_page: url });
    const path = l.url.toLowerCase();
    if (s.follow_support_pages && path.includes(slug) && /support|download|document|resource|manual/.test(path)
        && (!locale || path.includes('/' + locale.toLowerCase() + '/'))
        && !read.some(r => r.startsWith(l.url)) && !pages.includes(l.url)) pages.push(l.url);
  }
}
return { json: { ...p, page_links: found, pages_read: read } };

