// A link counts when it has a document word and is either a file or names this model. Download centre pages and FAQ articles don't count.
// Generic category pages and FAQ articles don't count, however often they say "install".
const looksLikeDoc = (c, p) => {
  if (SKIP.test(c.url)) return false;
  const slug = p.model.toLowerCase().replace(/\([^)]*\)/g, '').trim().replace(/[\s_]+/g, '-');
  const names = c.url.toLowerCase().includes(slug) || !!findModel(p.model, s.family_prefixes, c.title);
  const words = DOC_WORDS.test(c.url + ' ' + c.title) || /techspecs/i.test(c.url);
  if (HUB.test(c.url) && !IS_FILE.test(c.url)) return false;
  return words && (IS_FILE.test(c.url) || names);
};
// DataForSEO returns some results as google.com/goto links: follow them to the real address.
const resolve = async url => {
  let u = url;
  for (let hop = 0; hop < 4 && /^https?:\/\/(www\.)?google\.[a-z.]+\/(goto|url)\?/i.test(u); hop++) {
    try {
      const r = await this.helpers.httpRequest({ url: u, method: 'GET', disableFollowRedirect: true, returnFullResponse: true,
        ignoreHttpStatusErrors: true, headers: { 'User-Agent': s.user_agent }, timeout: 15000 });
      const loc = (r.headers || {}).location;
      if (!loc) break;
      u = loc.startsWith('/') ? 'https://www.google.com' + loc : loc;
    } catch (e) { break; }
  }
  return u;
};
const out = [];
for (const [i, item] of $input.all().entries()) {
  // Two ways in: straight from Collect page links, or through the search (whose reply replaced the item).
  const p = item.json.product_id ? item.json : $('Collect page links').itemMatching(i).json;
  const raw = item.json.tasks ? (item.json.tasks[0] && item.json.tasks[0].result && item.json.tasks[0].result[0]
    ? item.json.tasks[0].result[0].items || [] : []).filter(r => r.type === 'organic').map(r => ({ url: r.url, title: r.title || '', snippet: r.description || '' }))
    : (p.cached_results || []);
  const results = [];
  for (const r of raw) results.push({ ...r, url: await resolve(r.url) });
  const all = [...p.page_links.map(l => ({ ...l, found_via: 'manufacturer page' })),
               ...results.map(r => ({ ...r, found_via: 'search', source_page: '' }))];
  const seen = new Set(), picked = [];
  for (const c of all) {
    const url = direct(c.url);
    const h = host(url);
    if (seen.has(url) || existing.has(p.product_id + ' ' + url)) continue;
    seen.add(url);
    if (!p.domains.some(d => h === d || h.endsWith('.' + d)) || /^(community|forum|forums|discuss|answers|uat|staging|stage|dev|test|beta)\./.test(h)) continue;
    if (!looksLikeDoc({ url, title: c.title }, p)) continue;
    picked.push({ ...c, url });
  }
  // PDFs first, then the manufacturer page's own links, capped per product.
  picked.sort((a, b) => (/\.pdf(\?|$)/i.test(b.url) - /\.pdf(\?|$)/i.test(a.url)) || (a.found_via === 'search') - (b.found_via === 'search'));
