// Document types, most specific first: a declaration of conformity often also says "user manual".
const TYPE_RULES = [
  ['compliance', /declaration of conformity|eu declaration|uk declaration|certificate of conformity|\bdoc\b.*conformity/i, /[_-]doc\.pdf|\/compliance\/|declaration|conformity/i],
  ['datasheet', /\bdata ?sheet\b|technical specifications|spec(ification)? sheet/i, /datasheet|data[_ -]sheet|[_-]ds\.pdf|\/ds\/|techspecs|spec[_ -]?sheet/i],
  ['setup', /quick (start|installation)|installation guide|setup guide|getting started/i, /qsg|qig|quick[_ -]?start|quick[_ -]?install|installation|setup[_ -]guide/i],
  ['manual', /user'?s? (guide|manual)|instruction manual|reference manual|owner'?s manual|operation manual/i, /user[_ -]?guide|user[_ -]?manual|[_-]ug[_.-]|manual/i],
];
const LABELS = { manual: 'User manual', setup: 'Setup guide', datasheet: 'Datasheet', compliance: 'Compliance document' };
const typeOf = (head, urlTitle) => {
  for (const [t, inText] of TYPE_RULES) if (head && inText.test(head)) return t;
  for (const [t, , inUrl] of TYPE_RULES) if (inUrl.test(urlTitle)) return t;
  return null;
};

// Model keys: the full model number first, then variants (no colour suffix, no family prefix).
const decode = t => { try { return decodeURIComponent(t); } catch (e) { return String(t || ''); } };
const modelKeys = (model, prefixes) => {
  const full = String(model || '').replace(/\([^)]*\)/g, '').trim();
  const keys = [full, full.replace(/[-\s](B|W|BK|WH|BLK|WHT|BLACK|WHITE)$/i, '')];
  for (const k of [...keys]) for (const p of prefixes) keys.push(k.replace(new RegExp('^' + p + '[\\s_-]+', 'i'), ''));
  return [...new Set(keys)].filter(k => k.length >= 4);
};
// Whole tokens only: "C211" never matches "C2110", and "Tapo C211" also matches "Tapo_C211" or "tapo-c211".
const findModel = (model, prefixes, text) => {
  const hay = decode(text);
  const keys = modelKeys(model, prefixes);
  for (const key of keys) {
    const tokens = key.match(/[a-z]+|\d+/gi) || [];
    if (!tokens.length) continue;
    const re = new RegExp('(^|[^a-z0-9])(' + tokens.join('[\\s_\\-]*') + ')(?=$|[^a-z0-9])', 'i');
    const m = re.exec(hay);
    if (!m) continue;
    // "VIGI C540-W" or "UACC-G5-PTZ-ICM": a hyphen and more characters make it another model.
    const after = hay.slice(m.index + m[0].length, m.index + m[0].length + 8);
    const longer = /^-[a-z0-9]/i.test(after) ? (m[2] + after.match(/^-[a-z0-9]+/i)[0]) : '';
    return { key, quote: m[2], variant: key !== keys[0], longer };
  }
