const s = $('Find settings').first().json;
const excludes = s.exclude_patterns.map(x => new RegExp(x, 'i'));
const now = new Date().toISOString();
const rows = $input.all().map((item, i) => {
  const c = $('Pick candidates').itemMatching(i).json;
  const row = (extra) => ({ json: { product_id: c.product_id, product_title: c.product_title, model: c.model, url: c.url,
    source_page: c.source_page || '', found_via: c.found_via || '', doc_title: c.doc_title || '', found_at: now,
    doc_type: '', label: '', evidence: '', fingerprint: '', file_url: '', mime: '', size_kb: 0, ...extra }, pairedItem: { item: i } });
  if (c.status) return row({ status: c.status, reason: c.reason });

  const head = $('Check the link').itemMatching(i).json;
  const h = head.headers || {};
  const status = Number(head.statusCode || 0);
  if (status !== 200) return row({ status: 'rejected', reason: 'link failed (' + (status || (head.error || {}).message || 'no reply') + ')' });
  const mime = String(h['content-type'] || '').split(';')[0].toLowerCase();
  const sizeKb = Math.round(Number(h['content-length'] || 0) / 1024);
  // The same file behind five regional links has one ETag (or one size and date), so this is the duplicate check.
  const fileUrl = c.url;
  const fp = h.etag ? 'etag ' + h.etag : h['content-length'] ? mime + ' ' + h['content-length'] + ' ' + (h['last-modified'] || '') : '';
  const raw = String(item.json.html || '');
  const text = (raw ? raw.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ') : raw)
    .replace(/&nbsp;|&#160;/g, ' ').replace(/\s+/g, ' ').trim();
  const title = (c.doc_title || decode(c.url.split('/').filter(Boolean).pop() || '')).replace(/\s+download$/i, '');
  const urlTitle = c.url + ' ' + title + ' ' + (c.snippet || '');
  const type = typeOf(text.slice(0, 1500), decode(urlTitle));
  const base = { doc_title: title.slice(0, 200), fingerprint: fp, file_url: fileUrl, mime, size_kb: sizeKb };

  if (excludes.some(re => re.test(urlTitle))) return row({ ...base, status: 'rejected', reason: 'matches exclude_patterns' });
