  if (type === 'compliance' && !s.include_compliance) return row({ ...base, status: 'rejected', reason: 'compliance documents are off' });

  const inName = findModel(c.model, s.family_prefixes, urlTitle);
  const inText = text.length >= 200 ? findModel(c.model, s.family_prefixes, text) : null;
  const typed = { ...base, doc_type: type, label: LABELS[type] };
  // A file that doesn't name the model may be a family guide that covers it: a person decides. A page we read that doesn't name it is out.
  if (!inName && !inText) return text.length >= 200
    ? row({ ...typed, status: 'rejected', reason: 'model not named in the link or the page' })
    : row({ ...typed, status: 'review', reason: 'model not named in the link: open the file to check it covers ' + c.model, evidence: 'linked from ' + (c.found_via === 'search' ? 'a search on the manufacturer site' : 'the manufacturer page') });

