  const ev = (inName || inText);
  if (!inName) { st = 'review'; why = 'model only in the page text (a family guide?)'; }
  else if (inName.longer) { st = 'review'; why = 'names ' + inName.longer + ': a different model?'; }
  else if (inName.variant) { st = 'review'; why = 'matched ' + inName.key + ', not the full model number ' + c.model; }
  else if (text.length >= 200 && !inText) { st = 'review'; why = 'model in the link but not on the page'; }
  if (s.review_mode === 'all' && st === 'ready') { st = 'review'; why = 'review_mode is all'; }
  if (s.review_mode === 'none' && st === 'review') st = 'ready';
  return row({ ...typed, status: st, reason: why, evidence: '"' + ev.quote + '" ' + where });
});
// A family guide (no model in its name) is only worth a look when nothing names the exact model for that type.
for (const r of rows) {
  const j = r.json;
  if (j.status !== 'review' || !/^model not named/.test(j.reason)) continue;
