] });
const docs = $input.all().map(i => i.json).sort((a, b) => a.id - b.id);
return [{ json: { blocks: card(docs[0], docs, $('Read the click').first().json.admin_url).blocks,
  text: 'Documents to check: ' + docs[0].product_title, product_id: docs[0].product_id,
  approved: $('Read the click').first().json.action === 'approve' } }];

const s = $('Publish settings').first().json;
let only = '';
try { only = String($('When Executed by Another Workflow').first().json.product_id || ''); } catch (e) {}
const rows = $input.all().map(i => i.json).filter(r => r.id && r.url);
const live = ['ready', 'uploading', 'published'];
const order = { manual: 0, setup: 1, datasheet: 2, compliance: 3 };
const rank = u => { const i = s.preferred_locales.findIndex(l => u.toLowerCase().includes(l)); return i < 0 ? 99 : i; };
const byProduct = {};
for (const r of rows) if (live.includes(r.status)) (byProduct[r.product_id] = byProduct[r.product_id] || []).push(r);
const todo = Object.keys(byProduct).filter(id => (!only || id === only) && byProduct[id].some(r => r.status !== 'published')).slice(0, s.max_products);
return todo.map(id => {
  // One copy of each file: the same fingerprint at another URL is a duplicate. Your preferred locale wins, then the oldest row.
  const docs = byProduct[id].slice().sort((a, b) => (a.status === 'published' ? -1 : 0) - (b.status === 'published' ? -1 : 0) || rank(a.url) - rank(b.url) || a.id - b.id);
  const seen = new Set(), keep = [], drop = [];
  for (const d of docs) { const k = d.fingerprint || d.url; if (seen.has(k)) drop.push(d); else { seen.add(k); keep.push(d); } }
  keep.sort((a, b) => order[a.doc_type] - order[b.doc_type] || (a.status === 'published' ? -1 : 0) - (b.status === 'published' ? -1 : 0) || rank(a.url) - rank(b.url) || a.id - b.id);
  // One of each type by default: two "setup guide" rows with the same title help nobody.
  const perType = {};
  for (const d of keep.splice(0)) { perType[d.doc_type] = (perType[d.doc_type] || 0) + 1; (perType[d.doc_type] <= s.max_per_type ? keep : drop).push(d); }
  return { json: { product_id: id, product_gid: 'gid://shopify/Product/' + id,
    docs: keep.slice(0, s.max_documents).map(d => ({ ...d,
      action: d.status === 'published' ? 'keep' : (!s.host_files || !/pdf/i.test(d.mime) || d.size_kb > s.max_file_mb * 1024) ? 'link' : d.file_id ? 'check' : 'upload' })),
    duplicates: drop.map(d => d.id), over_limit: keep.slice(s.max_documents).map(d => d.id) } };
});

// Why Code: a file goes through create, then PROCESSING, then READY over several runs, and each document's next step depends on that state.
const s = $('Publish settings').first().json;
const token = $('Get Shopify token for Publish').first().json.access_token;
const gqlCall = async (query, variables) => {
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://' + s.store_domain + '/admin/api/2026-10/graphql.json',
    headers: { 'X-Shopify-Access-Token': token }, body: { query, variables }, json: true, timeout: 45000 });
  if (r.errors && r.errors.length) throw new Error(r.errors.map(e => e.message).join('; '));
  return r.data;
};
const out = [];
for (const item of $('Plan the documents').all()) {
  const p = item.json;
  for (const d of p.docs) {
    try {
      if (d.action === 'upload') {
        // Shopify names the file after the address, so follow redirects to the real .pdf (a /document/42483/ link has no extension).
        let src = d.file_url || d.url;
        for (let hop = 0; hop < 5; hop++) {
          const r = await this.helpers.httpRequest({ url: src, method: 'HEAD', disableFollowRedirect: true, returnFullResponse: true,
            ignoreHttpStatusErrors: true, timeout: 20000 });
          const loc = (r.headers || {}).location;
          if (!loc || r.statusCode < 300 || r.statusCode >= 400) break;
          src = loc.startsWith('/') ? (/^https?:\/\/[^\/]+/i.exec(src) || [''])[0] + loc : loc;
        }
        src = src.replace(/ /g, '%20');
        const ext = (/\.(pdf|docx?|zip)(?:$|[?#])/i.exec(src) || [])[1];
        const name = (d.model + ' ' + d.label).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') + (ext ? '.' + ext.toLowerCase() : '');
        const x = await gqlCall(`mutation Upload($files: [FileCreateInput!]!) {
          fileCreate(files: $files) { files { id fileStatus } userErrors { field message } } }`,
          { files: [Object.assign({ originalSource: src, contentType: 'FILE', alt: (d.model + ' ' + d.label).slice(0, 512) }, ext ? { filename: name } : {})] });
        const err = x.fileCreate.userErrors.map(e => e.message).join('; ');
        if (err || !x.fileCreate.files[0]) { d.result = 'failed'; d.error = err || 'no file returned'; continue; }
        d.file_id = x.fileCreate.files[0].id; d.uploaded_at = new Date().toISOString(); d.action = 'check';
      }
      if (d.action === 'check') {
        const x = await gqlCall(`query File($id: ID!) { node(id: $id) { ... on GenericFile { fileStatus url fileErrors { message } } } }`, { id: d.file_id });
        const f = x.node || {};
        if (f.fileStatus === 'READY' && f.url) { d.result = 'ready'; d.link = f.url; }
        else if (f.fileStatus === 'FAILED') { d.result = 'failed'; d.error = (f.fileErrors || []).map(e => e.message).join('; ') || 'Shopify could not process the file'; }
        else if (d.uploaded_at && Date.now() - Date.parse(d.uploaded_at) > 24 * 3600 * 1000) { d.result = 'failed'; d.error = 'not READY after 24 hours'; }
        else d.result = 'pending';
      }
      if (d.action === 'link') { d.result = 'ready'; d.link = d.url; d.file_id = ''; }
      if (d.action === 'keep') d.result = 'keep';
    } catch (e) { d.result = 'failed'; d.error = String(e.message || e).slice(0, 300); }
  }
  out.push({ json: p });
}
return out;

