const now = new Date().toISOString();
const out = [];
$input.all().forEach((item, i) => {
  const p = $('Upload and check files').itemMatching(i).json;
  const entries = $('Write the document entries').itemMatching(i).json.data || {};
  const setErr = ((item.json.data || {}).metafieldsSet || {}).userErrors || [];
  let n = 0;
  for (const d of p.docs) {
    if (d.result === 'keep') continue;
    const row = { id: d.id, file_id: d.file_id || '', uploaded_at: d.uploaded_at || null };
    if (d.result === 'ready') {
      const e = entries['d' + n++] || {};
      const err = (e.userErrors || []).map(x => x.message).concat(setErr.map(x => x.message)).join('; ');
      Object.assign(row, err || !e.metaobject ? { status: 'failed', reason: err || 'entry not written' }
        : { status: 'published', metaobject_id: e.metaobject.id, published_at: now, reason: /^Approved by/.test(d.reason || '') ? d.reason : '' });
    } else if (d.result === 'pending') Object.assign(row, { status: 'uploading', reason: 'waiting for Shopify to process the file' });
    else Object.assign(row, { status: 'failed', reason: d.error });
    out.push({ json: Object.assign({ metaobject_id: d.metaobject_id || '', published_at: d.published_at || null, product_title: d.product_title }, row) });
  }
  for (const id of p.duplicates) out.push({ json: { id, status: 'duplicate', reason: 'same file, or another of the same type is shown', file_id: '', metaobject_id: '', uploaded_at: null, published_at: null } });
});
return out;

